// CrowdRelay decides WHEN to sweep and WHAT is admissible. This workflow only
// reads published text and reports what it read. It never judges a candidate
// and never invents a contact.
const e = $json;
if (!e || e.type !== 'viryaos.outreach.discovery_requested' || e.version !== 1) return [];
const d = e.data ?? {};
const requested = Number(d.requested_candidates ?? 0);
if (!Number.isInteger(requested) || requested < 1 || requested > 100) {
  throw new Error('Invalid discovery request');
}
const screening = d.screening_contract ?? {};
const queries = String($env.VIRYA_DISCOVERY_PLAYLIST_QUERIES || '')
  .split('|').map(q => q.trim()).filter(Boolean);
if (queries.length === 0) throw new Error('Set VIRYA_DISCOVERY_PLAYLIST_QUERIES');
if (!$env.SPOTIFY_CLIENT_ID || !$env.SPOTIFY_CLIENT_SECRET) {
  throw new Error('Missing Spotify app credentials');
}
return [{ json: {
  action_id: String(d.action_id || ''),
  event_id: e.id,
  requested,
  queries,
  // Published so a sweep can skip what CrowdRelay would refuse anyway. The
  // same rules are re-applied on ingest regardless of what this believed.
  min_followers: Number(screening.minimum_follower_count ?? 250),
  callback_path: String(d.callback_path || '/v1/admin/autopilot/outreach/candidates')
}}];

// One item per search query, carrying the token and the sweep parameters.
const token = $json.access_token;
if (!token) throw new Error('Spotify token missing');
const plan = $('Validate sweep request').first().json;
return plan.queries.map(q => ({ json: { ...plan, access_token: token, query: q } }));

// Extract a submission route ONLY where the curator published one for that
// purpose. Never infer an address, never pattern-guess from a name or domain:
// CrowdRelay refuses those as `route_inferred`, and a burned curator does not
// come back. The description snippet travels with every candidate, because a
// route no human can check later is refused as `evidence_missing`.
const plan = $('Validate sweep request').first().json;
const EMAIL = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i;
const FORM = /https?:\/\/[^\s"'<>]+/i;
// An address is only a submission route when the surrounding text says so.
const INTENT = /(submi|send|pitch|demo|promo|contact|wy[sś]lij|zg[lł]o[sś]|kontakt)/i;
const SELLS = /(paid\s*(placement|promo)|guaranteed\s*placement|buy\s*a?\s*spot|p[lł]atn[ae]\s*promocj)/i;
const out = [];
for (const item of $input.all()) {
  const playlists = item.json?.playlists?.items ?? [];
  for (const p of playlists) {
    if (!p || p.public === false) continue;
    const description = String(p.description || '').replace(/<[^>]*>/g, ' ').trim();
    if (!description) continue;
    const followers = Number(p.followers?.total ?? 0) || null;
    const sells = SELLS.test(description);
    const hasIntent = INTENT.test(description);
    const email = description.match(EMAIL)?.[0] ?? null;
    const url = description.match(FORM)?.[0] ?? null;
    let route_kind = null, route_value = null;
    if (email && hasIntent) { route_kind = 'email'; route_value = email; }
    else if (url && hasIntent) { route_kind = 'submission_form'; route_value = url; }
    if (!route_value) continue;
    out.push({ json: {
      target_kind: 'playlist',
      display_name: String(p.name || '').slice(0, 200),
      source: 'playlist_description',
      source_reference: String(p.external_urls?.spotify || ('spotify:playlist:' + p.id)).slice(0, 2048),
      // Verbatim, bounded. This is what a human re-reads to check the extraction.
      evidence: description.slice(0, 4000),
      route_kind,
      route_value: String(route_value).slice(0, 2048),
      // True only because the route was read out of text the curator published
      // for submissions. Anything worked out must be reported as false.
      route_is_published: true,
      fit_basis_points: Number($env.VIRYA_DISCOVERY_FIT_BASIS_POINTS || 7000),
      follower_count: followers,
      engagement_count: null,
      // Raw signals, not verdicts. CrowdRelay screens on these.
      sells_placement: sells,
      churns_indiscriminately: false
    }});
  }
}
// Deduplicate on contact identity before sending, so one batch cannot contain
// the same curator twice.
const seen = new Set();
const unique = out.filter(o => {
  const key = o.json.route_kind + ':' + o.json.route_value.toLowerCase();
  if (seen.has(key)) return false;
  seen.add(key); return true;
});
return unique.slice(0, Math.min(plan.requested, 100));

// Report the batch even when it is empty. CrowdRelay distinguishes a sweep
// that found nothing admissible — after which it stops asking — from one that
// was never answered, which stays an operator problem. Returning silently
// keeps the request alive and hides a broken sweep as a dry source.
const plan = $('Validate sweep request').first().json;
const candidates = $input.all().map(i => i.json);
return [{ json: {
  action_id: plan.action_id,
  callback_path: plan.callback_path,
  // Stable per sweep, so a retry of this workflow replays rather than
  // re-ingesting the same batch as a second operation.
  idempotency_key: 'outreach-discovery:' + plan.event_id,
  candidates
}}];

// A sweep that read published text and found no usable route is a real
// answer. CrowdRelay counts it as barren and backs off after three, which is
// the behaviour that stops the agent refreshing an empty inbox.
return [{ json: { swept: true, candidates: 0, note: 'no published submission route found' } }];
